import { z } from 'zod';
import { provenanceSchema } from '../provenance.ts';

/**
 * Maps of a game, taken from its wikis: interactive maps (Fandom "Interactive Maps" and the
 * DataMaps extension used by wiki.gg) and plain map images. Nothing is generated by AI.
 */

export const INTERACTIVE_MAP_KINDS = ['fandom', 'datamaps'] as const;
export const interactiveMapKindSchema = z.enum(INTERACTIVE_MAP_KINDS);

/** One interactive map a wiki has, before its markers are fetched. */
export const interactiveMapRefSchema = z.object({
  /** Name to show, without the `Map:` prefix. */
  title: z.string(),
  /** Full page title on the wiki, used to ask for the map. */
  page: z.string(),
  /** The map's page on the wiki. */
  pageUrl: z.string(),
  wikiName: z.string(),
  /** Article base of the wiki, used to ask for the full map. */
  wikiUrl: z.string(),
  kind: interactiveMapKindSchema,
});
export type InteractiveMapRef = z.infer<typeof interactiveMapRefSchema>;

export const wikiMapImageSchema = z.object({
  title: z.string(),
  thumbUrl: z.string(),
  pageUrl: z.string(),
  width: z.number(),
  height: z.number(),
  wikiName: z.string(),
});

export const gameMapsResponseSchema = z.object({
  /** Wikis that were searched, the one chosen for the game first. */
  wikis: z.array(z.object({ name: z.string(), url: z.string() })),
  interactive: z.array(interactiveMapRefSchema),
  images: z.array(wikiMapImageSchema),
  /** Area the run is in, to point it out on the map. */
  currentCheckpoint: z.string().nullable(),
});
export type GameMapsResponse = z.infer<typeof gameMapsResponseSchema>;

export const interactiveMapQuerySchema = z.object({
  wiki: z.url().max(300),
  title: z.string().trim().min(1).max(300),
});

export const interactiveMapSchema = z.object({
  title: z.string(),
  pageUrl: z.string(),
  wikiName: z.string(),
  kind: interactiveMapKindSchema,
  /** Background images; most maps have one, some have floors or worlds. */
  layers: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      imageUrl: z.string(),
      width: z.number(),
      height: z.number(),
    }),
  ),
  categories: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      color: z.string().nullable(),
      iconUrl: z.string().nullable(),
      count: z.number().int(),
    }),
  ),
  markers: z.array(
    z.object({
      id: z.string(),
      categoryId: z.string(),
      /** Background the marker belongs to; null when it shows on all of them. */
      layerId: z.string().nullable(),
      /** Position as a fraction of the image, from the top-left corner. */
      x: z.number(),
      y: z.number(),
      title: z.string(),
      description: z.string().nullable(),
      imageUrl: z.string().nullable(),
      link: z.string().nullable(),
    }),
  ),
  /** Markers named after where the run is now, and after the places it can go next. */
  highlights: z.object({ here: z.array(z.string()), next: z.array(z.string()) }),
  provenance: provenanceSchema,
});
export type InteractiveMap = z.infer<typeof interactiveMapSchema>;
